input.command:
cat > .tmp/tocsv.awk <<'AWK'
BEGIN { print "row_id,account_id,event_time,amount_usd,is_weekend,amount_7d" }
/:/ {
  line=$0
  # extract key
  if (match(line, /"[^"]+"[ \t]*:/)) {
    k=substr(line, RSTART+1, RLENGTH-1)
    sub(/"[ \t]*:.*/, "", k)
    # extract value: everything after the first colon
    v=line
    sub(/^[^:]*:[ \t]*/, "", v)
    sub(/,[ \t]*$/, "", v)            # strip trailing comma
    gsub(/^"|"$/, "", v)              # strip surrounding quotes
    val[k]=v
  }
}
/}/ {
  if ("row_id" in val) {
    printf "%s,%s,%s,%s,%s,%s\n", val["row_id"], val["account_id"], val["event_time"], val["amount_usd"], val["is_weekend"], val["amount_7d"]
    delete val
  }
}
AWK
awk -f .tmp/tocsv.awk .tmp/derived.json > .tmp/derived.csv
echo "rows (incl header): $(wc -l < .tmp/derived.csv)"
head -4 .tmp/derived.csv
echo "..."
tail -2 .tmp/derived.csv

